cat > a.mjs <<'E'
import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:65166');
await p.fill('input[type=email]','ops@lab.test');await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');await p.waitForTimeout(1500);
await p.click('text=Pipeline');await p.waitForTimeout(1000);
const want=['Picking','Packing','Quality check','Credit check','Shipping','Intake','Invoicing'];
const names=()=>p.$$eval('#pl .nm',e=>e.map(x=>x.textContent));
for(let i=0;i<want.length;i++){
 const cur=await names(); if(cur[i]===want[i])continue;
 const from=await p.locator('#pl li').nth(cur.indexOf(want[i])).locator('.h').boundingBox();
 const to=await p.locator('#pl li').nth(i).boundingBox();
 await p.mouse.move(from.x+5,from.y+5);await p.mouse.down();
 await p.mouse.move(from.x+5,(from.y+to.y)/2,{steps:5});
 await p.mouse.move(from.x+5,to.y+3,{steps:10});await p.mouse.up();
 console.log(await names());
}
await p.click('#save');await p.waitForTimeout(1000);
console.log(await names(), await p.innerText('#done'));
await b.close();
E
